                        root.TryGetProperty("data",out _) ||
                        root.GetProperty("errors").ValueKind!=JsonValueKind.Array ||
                        string.IsNullOrWhiteSpace(expectedCode) ||
                        root.GetProperty("code").GetString()!=expectedCode)
